fn prime_num(n: u64) -> bool {
    if n < 2 {
        return false; // Since we assume n is at least 2, this is just a safety check.
    }
    if n == 2 {
        return true; // 2 is the only even prime number.
    }
    if n % 2 == 0 {
        return false; // Exclude all other even numbers.
    }
    
    let limit = (n as f64).sqrt() as u64; // Calculate the square root of n.
    for k in 3..=limit {
        if n % k == 0 {
            return false; // Found a divisor, so n is not prime.
        }
    }
    
    true // No divisors found, n is prime.
}

fn main() {
    // Example usage
    let number = 29;
    println!("Is {} prime? {}", number, prime_num(number)); // Should print true
}